    "member_monthly_orders": "WITH month_spine AS (\n  SELECT DISTINCT\n    date_trunc('month', date_day)::DATE AS month_start,\n    (date_trunc('month', date_day) + INTERVAL '1 month' - INTERVAL '1 day')::DATE AS month_end\n  FROM {{ ref('time_spine') }}\n),\nmember_orders AS (\n  SELECT\n    member_id,\n    date_trunc('month', ordered_at)::DATE AS month_start,\n    COUNT(order_id) AS valid_orders,\n    SUM(paid_cents - refund_cents) AS net_cents\n  FROM {{ ref('orders') }}\n  WHERE status = 'paid' AND paid_cents - refund_cents > 0\n  GROUP BY member_id, date_trunc('month', ordered_at)::DATE\n),\nactive_members AS (\n  SELECT DISTINCT member_id, month_start FROM member_orders\n  UNION\n  SELECT c.member_id, ms.month_start\n  FROM {{ ref('cards') }} c\n  CROSS JOIN month_spine ms\n  WHERE c.card_type IN ('悦享年卡', '家庭季卡')\n    AND c.valid_from <= ms.month_end\n    AND c.valid_until > ms.month_end\n    AND (c.ended_at IS NULL OR c.ended_at > ms.month_end)\n),\nmember_qualification AS (\n  SELECT\n    am.member_id,\n    am.month_start,\n    ms.month_end,\n    CASE WHEN EXISTS (\n      SELECT 1\n      FROM {{ ref('cards') }} c\n      WHERE c.member_id = am.member_id\n        AND c.card_type IN ('悦享年卡', '家庭季卡')\n        AND c.valid_from <= ms.month_end\n        AND c.valid_until > ms.month_end\n        AND (c.ended_at IS NULL OR c.ended_at > ms.month_end)\n    ) THEN 1 ELSE 0 END AS is_paid_qualified\n  FROM active_members am\n  JOIN month_spine ms ON am.month_start = ms.month_start\n)\nSELECT\n  mq.member_id || '_' || strftime(mq.month_start, '%Y-%m-%d') AS member_month_id,\n  mq.member_id,\n  mq.month_start,\n  mq.is_paid_qualified,\n  COALESCE(mo.valid_orders, 0) AS valid_orders,\n  COALESCE(mo.net_cents, 0) AS net_cents\nFROM member_qualification mq\nLEFT JOIN member_orders mo\n  ON mq.member_id = mo.member_id AND mq.month_start = mo.month_start"
